-- ==== 01_messaging.sql ====
-- messaging_nov22 01: company messages (job chats + direct messages), staged Nov 22 2026. NOT applied.
-- Read on live Nov 22 (read only): public.companies, public.company_members (UNIQUE user_id; role foreman|pipelayer|pm),
-- pb_reports.managers, pb_prod.entries / run_records / site_log (user_id, company_id, job_key, updated_at), pb_prod.crew_links,
-- pb_pm.settings.tz (default America/Chicago), pb_prod.push_prefs.tz, pb_push.outbox (+ check pb_push_out_type),
-- pb_push.kick(), pb_push.is_service(), pb_audit.direct_write(), pb_billing.storage_room(uuid,text,integer),
-- pb_crew.display_name(uuid,uuid). Nothing live is replaced; the only live object changed is the pb_push_out_type check
-- (gets 'message'). Job membership (Tommy, Nov 22 answer 47): everyone ASSIGNED to the job, read from what the app assigns
-- today: PMs/supers from pb_pm.job_pms; foremen from inspection/test items (pb_daily.items.foreman_uid), crew runs assigned
-- to them (pb_prod.entries.assigned_to) and dailies the office filled for them (pb_daily.reports.for_foreman); plus the
-- company account and managers. Nobody assigned -> fallback (said on Chat info): foremen who worked the job in 120 days,
-- and every PM/super when no PM/super is assigned (as pb_pm.job_alert_recipients does for job alerts).
-- Run as postgres in one transaction (apply/01_messaging.apply.sql). Safe to run twice.
-- Undo: undo/99_undo_01.sql.

create schema if not exists pb_msg;
revoke all on schema pb_msg from public;
revoke all on schema pb_msg from anon, authenticated;

-- ============================ tables ============================
create table if not exists pb_msg.chats (
  id                 uuid primary key default gen_random_uuid(),
  company_id         uuid not null,
  kind               text not null check (kind in ('job', 'dm')),
  job_key            text,
  job_number         text,
  dm_a               uuid,
  dm_b               uuid,
  include_pipelayers boolean not null default false,
  pipelayer_history  text not null default 'from_added' check (pipelayer_history in ('from_added', 'all')),
  created_by         uuid not null,
  created_at         timestamptz not null default now(),
  last_seq           bigint not null default 0,
  last_at            timestamptz,
  closed_at          timestamptz,
  closed_by          uuid,
  settings_ver       integer not null default 0,
  constraint pb_msg_chat_shape check (
    (kind = 'job' and job_key is not null and job_key <> '' and dm_a is null and dm_b is null)
    or (kind = 'dm' and job_key is null and dm_a is not null and dm_b is not null and dm_a < dm_b))
);
create unique index if not exists pb_msg_chats_job on pb_msg.chats (company_id, job_key) where kind = 'job';
create unique index if not exists pb_msg_chats_dm on pb_msg.chats (company_id, dm_a, dm_b) where kind = 'dm';
create index if not exists pb_msg_chats_recent on pb_msg.chats (company_id, last_at desc nulls last);

create table if not exists pb_msg.people (
  chat_id    uuid not null references pb_msg.chats(id),
  user_id    uuid not null,
  state      text not null check (state in ('in', 'out', 'off')),  -- out: taken off by the office; off: pipelayers switched off
  how        text not null check (how in ('auto', 'office', 'dm', 'creator')),
  since      timestamptz not null default now(),
  since_seq  bigint not null default 0,                             -- messages with seq > since_seq are theirs (pipelayers, "from when added")
  changed_by uuid,
  changed_at timestamptz not null default now(),
  primary key (chat_id, user_id)
);
create index if not exists pb_msg_people_user on pb_msg.people (user_id) where state = 'in';

create table if not exists pb_msg.messages (
  id          uuid primary key default gen_random_uuid(),
  chat_id     uuid not null references pb_msg.chats(id),
  company_id  uuid not null,
  seq         bigint not null,
  author      uuid not null,
  author_name text,
  client_id   text not null check (client_id ~ '^[A-Za-z0-9_-]{8,64}$'),
  body        text check (body is null or length(body) <= 4000),
  photos      jsonb not null default '[]'::jsonb check (jsonb_typeof(photos) = 'array' and jsonb_array_length(photos) <= 6),
  created_at  timestamptz not null default now(),
  phone_at    timestamptz,
  edited_at   timestamptz,
  deleted_at  timestamptz,
  deleted_by  uuid,
  version     integer not null default 1,
  unique (chat_id, seq),
  unique (chat_id, author, client_id)
);
create index if not exists pb_msg_messages_author_day on pb_msg.messages (author, created_at desc);
create index if not exists pb_msg_messages_company_age on pb_msg.messages (company_id, created_at);

create table if not exists pb_msg.message_versions (
  id         bigint generated always as identity primary key,
  message_id uuid not null,
  chat_id    uuid not null,
  company_id uuid not null,
  version    integer not null,
  body       text,
  photos     jsonb,
  action     text not null check (action in ('edit', 'delete')),
  by_user    uuid,
  at         timestamptz not null default now(),
  unique (message_id, version)
);

create table if not exists pb_msg.reads (chat_id uuid not null, user_id uuid not null, last_seq bigint not null default 0, at timestamptz not null default now(), primary key (chat_id, user_id));
create table if not exists pb_msg.mutes (chat_id uuid not null, user_id uuid not null, at timestamptz not null default now(), primary key (chat_id, user_id));
create table if not exists pb_msg.person_prefs (
  user_id    uuid primary key,
  push       boolean not null default true,
  words      boolean not null default true,     -- show the first 60 characters on the lock screen
  quiet_on   boolean not null default true,
  quiet_from time not null default '19:00',
  quiet_to   time not null default '06:00',
  updated_at timestamptz not null default now()
);
create table if not exists pb_msg.company_settings (
  company_id uuid primary key,
  retention  text not null default 'forever' check (retention in ('forever', '13m')),
  updated_by uuid,
  updated_at timestamptz not null default now()
);
create table if not exists pb_msg.company_log (id bigint generated always as identity primary key, company_id uuid not null, by_user uuid, at timestamptz not null default now(), what text not null, old_value jsonb, new_value jsonb);
create table if not exists pb_msg.chat_log (id bigint generated always as identity primary key, chat_id uuid not null, company_id uuid not null, by_user uuid, at timestamptz not null default now(), what text not null, target_user uuid, old_value jsonb, new_value jsonb);
create index if not exists pb_msg_chat_log_chat on pb_msg.chat_log (chat_id, at desc);
create table if not exists pb_msg.archives (
  id           uuid primary key default gen_random_uuid(),
  chat_id      uuid not null,
  company_id   uuid not null,
  reason       text not null check (reason in ('closed', 'office', 'idle')),
  state        text not null default 'queued' check (state in ('queued', 'working', 'done', 'failed', 'purge', 'purged')),
  requested_by uuid,
  requested_at timestamptz not null default now(),
  started_at   timestamptz,
  done_at      timestamptz,
  attempts     integer not null default 0,
  files        jsonb not null default '[]'::jsonb,   -- [{path, bytes, sha256}]
  bytes        bigint,
  messages     integer,
  photos       integer,
  upto_seq     bigint,
  note         text
);
create index if not exists pb_msg_archives_chat on pb_msg.archives (chat_id, requested_at desc);
create index if not exists pb_msg_archives_todo on pb_msg.archives (state, requested_at) where state in ('queued', 'working', 'purge');
create table if not exists pb_msg.push_pending (chat_id uuid not null, user_id uuid not null, outbox_id uuid not null, n integer not null default 1, last_msg uuid, primary key (chat_id, user_id));
create table if not exists pb_msg.downloads (id bigint generated always as identity primary key, archive_id uuid not null, chat_id uuid not null, company_id uuid not null, path text not null, by_user uuid not null, at timestamptz not null default now());
create index if not exists pb_msg_downloads_path on pb_msg.downloads (path, by_user, at desc);
create table if not exists pb_msg.purge_log (id bigint generated always as identity primary key, company_id uuid not null, at timestamptz not null default now(), messages integer, versions integer, before_at timestamptz);

do $t$ declare t text; begin
  foreach t in array array['chats','people','messages','message_versions','reads','mutes','person_prefs','company_settings','company_log','chat_log','archives','push_pending','purge_log','downloads'] loop
    execute format('alter table pb_msg.%I enable row level security', t);
    execute format('revoke all on table pb_msg.%I from public', t);
    execute format('revoke all on table pb_msg.%I from anon, authenticated', t);
  end loop;
end $t$;

-- ============================ records guards (like records B9) ============================
create or replace function pb_msg.messages_guard() returns trigger
language plpgsql set search_path to '' as $f$
begin
  if tg_op = 'DELETE' then
    if coalesce(current_setting('pb.allow_record_delete', true), '') = 'on' then return old; end if;
    raise exception 'pb:history_is_permanent';
  end if;
  if (new.id, new.chat_id, new.company_id, new.seq, new.author, new.author_name, new.client_id, new.created_at, new.phone_at)
     is distinct from (old.id, old.chat_id, old.company_id, old.seq, old.author, old.author_name, old.client_id, old.created_at, old.phone_at) then
    raise exception 'pb:history_is_permanent';
  end if;
  if old.deleted_at is not null then raise exception 'pb:history_is_permanent'; end if;     -- a deleted message stays deleted
  if (new.body, new.photos, new.deleted_at) is not distinct from (old.body, old.photos, old.deleted_at) then
    if new.version <> old.version or new.edited_at is distinct from old.edited_at or new.deleted_by is distinct from old.deleted_by then raise exception 'pb:history_is_permanent'; end if;
    return new;
  end if;
  if new.version <> old.version + 1 then raise exception 'pb:history_is_permanent'; end if;
  insert into pb_msg.message_versions (message_id, chat_id, company_id, version, body, photos, action, by_user)
    values (old.id, old.chat_id, old.company_id, old.version, old.body, old.photos,
            case when new.deleted_at is not null then 'delete' else 'edit' end, coalesce(new.deleted_by, auth.uid()));
  return new;
end $f$;
create or replace function pb_msg.permanent() returns trigger
language plpgsql set search_path to '' as $f$
begin
  if tg_op = 'DELETE' and coalesce(current_setting('pb.allow_record_delete', true), '') = 'on' then return old; end if;
  raise exception 'pb:history_is_permanent';
end $f$;
revoke all on function pb_msg.messages_guard() from public, anon, authenticated;
revoke all on function pb_msg.permanent() from public, anon, authenticated;
drop trigger if exists messages_guard on pb_msg.messages;
create trigger messages_guard before update or delete on pb_msg.messages for each row execute function pb_msg.messages_guard();
drop trigger if exists messages_no_truncate on pb_msg.messages;
create trigger messages_no_truncate before truncate on pb_msg.messages for each statement execute function pb_msg.permanent();
drop trigger if exists versions_permanent on pb_msg.message_versions;
create trigger versions_permanent before update or delete on pb_msg.message_versions for each row execute function pb_msg.permanent();
drop trigger if exists versions_no_truncate on pb_msg.message_versions;
create trigger versions_no_truncate before truncate on pb_msg.message_versions for each statement execute function pb_msg.permanent();
drop trigger if exists chat_log_permanent on pb_msg.chat_log;
create trigger chat_log_permanent before update or delete on pb_msg.chat_log for each row execute function pb_msg.permanent();
drop trigger if exists downloads_permanent on pb_msg.downloads;
create trigger downloads_permanent before update or delete on pb_msg.downloads for each row execute function pb_msg.permanent();
drop trigger if exists company_log_permanent on pb_msg.company_log;
create trigger company_log_permanent before update or delete on pb_msg.company_log for each row execute function pb_msg.permanent();
do $a$ declare t text; begin
  if to_regprocedure('pb_audit.direct_write()') is null then return; end if;   -- (throwaway local database: no admin log)
  foreach t in array array['chats','people','messages','message_versions','company_settings','archives'] loop
    execute format('drop trigger if exists zz_pb_audit on pb_msg.%I', t);
    execute format('create trigger zz_pb_audit after insert or delete or update on pb_msg.%I for each row execute function pb_audit.direct_write()', t);
  end loop;
end $a$;

-- ============================ who is who ============================
-- the company a person belongs to now: their member row (one per person on live), else the company they own
create or replace function pb_msg.my_co(p_uid uuid) returns uuid
language sql stable security definer set search_path to '' as $f$
  select coalesce(
    (select m.company_id from public.company_members m where m.user_id = p_uid order by m.created_at desc nulls last limit 1),
    (select c.id from public.companies c where c.owner_user_id = p_uid order by (c.status = 'active') desc, c.created_at desc limit 1))
$f$;
-- their place in that company now: office (company account, managers) | pm (PMs and supers) | foreman | pipelayer | null.
-- No status check: a lapsed company can still read its messages; posting needs an active company (pb_msg.co_active).
create or replace function pb_msg.role_in(p_uid uuid, p_co uuid) returns text
language sql stable security definer set search_path to '' as $f$
  select case
    when p_uid is null or p_co is null then null
    when exists (select 1 from public.companies c where c.id = p_co and c.owner_user_id = p_uid) then 'office'
    else (select case when m.role = 'pm' then 'pm'
                      when exists (select 1 from pb_reports.managers g where g.company_id = p_co and g.user_id = p_uid) then 'office'
                      when m.role = 'foreman' then 'foreman' else 'pipelayer' end
            from public.company_members m where m.user_id = p_uid and m.company_id = p_co limit 1)
  end
$f$;
create or replace function pb_msg.co_active(p_co uuid) returns boolean
language sql stable security definer set search_path to '' as $f$ select exists (select 1 from public.companies c where c.id = p_co and c.status = 'active') $f$;
create or replace function pb_msg.name_of(p_co uuid, p_uid uuid) returns text
language plpgsql stable security definer set search_path to '' as $f$
declare v text;
begin
  begin v := pb_crew.display_name(p_co, p_uid); exception when others then v := null; end;
  if v is null or btrim(v) = '' then select split_part(u.email, '@', 1) into v from auth.users u where u.id = p_uid; end if;
  return left(coalesce(nullif(btrim(v), ''), 'Someone'), 80);
end $f$;
-- filed work on this job in the last 120 days (the app's job list window): production entry, run record, job book / site log
create or replace function pb_msg.on_job(p_uid uuid, p_co uuid, p_jk text) returns boolean
language sql stable security definer set search_path to '' as $f$
  select exists (select 1 from pb_prod.entries e where e.user_id = p_uid and e.company_id = p_co and e.job_key = p_jk and not coalesce(e.voided, false) and e.updated_at > now() - interval '120 days')
      or exists (select 1 from pb_prod.run_records r where r.user_id = p_uid and r.company_id = p_co and r.job_key = p_jk and r.removed_at is null and r.updated_at > now() - interval '120 days')
      or exists (select 1 from pb_prod.site_log s where s.user_id = p_uid and s.company_id = p_co and s.job_key = p_jk and s.updated_at > now() - interval '120 days')
$f$;

-- assigned to the job (what the app assigns today; see the header)
create or replace function pb_msg.pm_assigned(p_uid uuid, p_co uuid, p_jk text) returns boolean
language plpgsql stable security definer set search_path to '' as $f$
begin
  return exists (select 1 from pb_pm.job_pms a where a.company_id = p_co and a.job_key = p_jk and a.user_id = p_uid and a.ended_at is null);
exception when undefined_table then return false;
end $f$;
create or replace function pb_msg.any_pm(p_co uuid, p_jk text) returns boolean
language plpgsql stable security definer set search_path to '' as $f$
begin
  return exists (select 1 from pb_pm.job_pms a where a.company_id = p_co and a.job_key = p_jk and a.ended_at is null and pb_msg.role_in(a.user_id, p_co) = 'pm');
exception when undefined_table then return false;
end $f$;
create or replace function pb_msg.fm_assigned(p_uid uuid, p_co uuid, p_jk text) returns boolean
language plpgsql stable security definer set search_path to '' as $f$
declare v boolean := false;
begin
  begin v := exists (select 1 from pb_daily.items i where i.company_id = p_co and i.job_key = p_jk and i.foreman_uid = p_uid and i.status = 'open'); exception when undefined_table then v := false; end;
  if v then return true; end if;
  if exists (select 1 from pb_prod.entries e where e.company_id = p_co and e.job_key = p_jk and e.assigned_to = p_uid and not coalesce(e.voided, false) and e.updated_at > now() - interval '120 days') then return true; end if;
  begin v := exists (select 1 from pb_daily.reports r where r.company_id = p_co and r.job_key = p_jk and r.for_foreman = p_uid and r.received_at > now() - interval '120 days'); exception when undefined_table then v := false; end;
  return v;
end $f$;
create or replace function pb_msg.any_fm(p_co uuid, p_jk text) returns boolean
language plpgsql stable security definer set search_path to '' as $f$
declare v boolean := false;
begin
  begin v := exists (select 1 from pb_daily.items i where i.company_id = p_co and i.job_key = p_jk and i.foreman_uid is not null and i.status = 'open' and pb_msg.role_in(i.foreman_uid, p_co) = 'foreman'); exception when undefined_table then v := false; end;
  if v then return true; end if;
  if exists (select 1 from pb_prod.entries e where e.company_id = p_co and e.job_key = p_jk and e.assigned_to is not null and not coalesce(e.voided, false) and e.updated_at > now() - interval '120 days' and pb_msg.role_in(e.assigned_to, p_co) = 'foreman') then return true; end if;
  begin v := exists (select 1 from pb_daily.reports r where r.company_id = p_co and r.job_key = p_jk and r.for_foreman is not null and r.received_at > now() - interval '120 days' and pb_msg.role_in(r.for_foreman, p_co) = 'foreman'); exception when undefined_table then v := false; end;
  return v;
end $f$;
-- who is in a job chat, as words for Chat info: assigned, or the fallback
create or replace function pb_msg.rule(p_co uuid, p_jk text) returns jsonb
language sql stable security definer set search_path to '' as $f$
  select jsonb_build_object('pms', case when pb_msg.any_pm(p_co, p_jk) then 'assigned' else 'all' end,
                            'foremen', case when pb_msg.any_fm(p_co, p_jk) then 'assigned' else 'worked' end)
$f$;
-- a job chat (also before it exists: p_chat null): office | pm | foreman | pipelayer | null
create or replace function pb_msg.jq(p_co uuid, p_jk text, p_include boolean, p_chat uuid, p_uid uuid) returns text
language plpgsql stable security definer set search_path to '' as $f$
declare r text; p pb_msg.people; added boolean := false; f uuid;
begin
  r := pb_msg.role_in(p_uid, p_co);
  if r is null then return null; end if;                             -- not in the company (now): nothing, ever
  if r = 'office' then return 'office'; end if;                      -- the company account and managers: every job chat
  if p_chat is not null then
    select * into p from pb_msg.people where chat_id = p_chat and user_id = p_uid;
    if found and p.state = 'out' then return null; end if;           -- taken off by the office
    added := found and p.state = 'in' and p.how = 'office';          -- the office added them to this chat
  end if;
  if r = 'pm' then
    return case when added or pb_msg.pm_assigned(p_uid, p_co, p_jk) or not pb_msg.any_pm(p_co, p_jk) then 'pm' end;
  end if;
  if r = 'foreman' then
    return case when added or pb_msg.fm_assigned(p_uid, p_co, p_jk) or (not pb_msg.any_fm(p_co, p_jk) and pb_msg.on_job(p_uid, p_co, p_jk)) then 'foreman' end;
  end if;
  if not coalesce(p_include, false) then return null; end if;        -- pipelayers only when the office included them
  if added or pb_msg.on_job(p_uid, p_co, p_jk) then return 'pipelayer'; end if;
  select l.foreman_id into f from pb_prod.crew_links l where l.pipelayer_id = p_uid and l.company_id = p_co and l.ended_at is null limit 1;
  if f is not null and pb_msg.jq(p_co, p_jk, false, p_chat, f) = 'foreman' then return 'pipelayer'; end if;  -- on the crew of a foreman in the chat
  return null;
end $f$;
-- may this person be in this chat now, and as what: office | pm | foreman | pipelayer | dm | null
create or replace function pb_msg.qual(p_chat uuid, p_uid uuid) returns text
language plpgsql stable security definer set search_path to '' as $f$
declare c pb_msg.chats;
begin
  select * into c from pb_msg.chats where id = p_chat;
  if not found or p_uid is null then return null; end if;
  if c.kind = 'dm' then return case when p_uid in (c.dm_a, c.dm_b) and pb_msg.role_in(p_uid, c.company_id) is not null then 'dm' end; end if;
  return pb_msg.jq(c.company_id, c.job_key, c.include_pipelayers, c.id, p_uid);
end $f$;
-- runs the chat (switches, people, close, archive, delete others' messages): the company account, managers, and the PMs/supers in it
create or replace function pb_msg.is_admin(p_chat uuid, p_uid uuid) returns boolean
language sql stable security definer set search_path to '' as $f$ select coalesce(pb_msg.qual(p_chat, p_uid) in ('office', 'pm'), false) $f$;
-- the company account itself (direct-message archives are its alone)
create or replace function pb_msg.is_owner(p_uid uuid, p_co uuid) returns boolean
language sql stable security definer set search_path to '' as $f$ select exists (select 1 from public.companies c where c.id = p_co and c.owner_user_id = p_uid) $f$;
-- what of the chat this person may read: -1 = all of it, n = messages with seq > n, null = nothing
create or replace function pb_msg.can_read(p_chat uuid, p_uid uuid) returns bigint
language plpgsql stable security definer set search_path to '' as $f$
declare q text; c pb_msg.chats; p pb_msg.people;
begin
  q := pb_msg.qual(p_chat, p_uid);
  if q is null then return null; end if;
  if q <> 'pipelayer' then return -1; end if;
  select * into p from pb_msg.people where chat_id = p_chat and user_id = p_uid;
  if not found or p.state <> 'in' then return null; end if;          -- a pipelayer is "added" when the roster records it
  select * into c from pb_msg.chats where id = p_chat;
  return case when c.pipelayer_history = 'all' then -1 else p.since_seq end;
end $f$;

-- write the roster: everyone who may be in the chat now gets a row (the time and message number they were added).
-- Called on every send, list (for the caller), open, and switch change. A row 'out' (taken off) is never re-added here.
create or replace function pb_msg.sync_one(p_chat uuid, p_uid uuid) returns void
language plpgsql security definer set search_path to '' as $f$
declare c pb_msg.chats; q text;
begin
  q := pb_msg.qual(p_chat, p_uid);
  if q is null then return; end if;
  select * into c from pb_msg.chats where id = p_chat;
  insert into pb_msg.people (chat_id, user_id, state, how, since, since_seq)
    values (p_chat, p_uid, 'in', case when q = 'dm' then 'dm' else 'auto' end, now(), c.last_seq)
  on conflict (chat_id, user_id) do update set state = 'in', since = now(), since_seq = c.last_seq, changed_at = now(), changed_by = null
    where pb_msg.people.state = 'off';
end $f$;
create or replace function pb_msg.sync_roster(p_chat uuid) returns void
language plpgsql security definer set search_path to '' as $f$
declare c pb_msg.chats; u uuid;
begin
  select * into c from pb_msg.chats where id = p_chat;
  if not found then return; end if;
  if c.kind = 'dm' then perform pb_msg.sync_one(p_chat, c.dm_a); perform pb_msg.sync_one(p_chat, c.dm_b); return; end if;
  for u in select m.user_id from public.company_members m where m.company_id = c.company_id
           union select co.owner_user_id from public.companies co where co.id = c.company_id loop
    perform pb_msg.sync_one(p_chat, u);
  end loop;
end $f$;

create or replace function pb_msg.can_post(p_chat uuid, p_uid uuid) returns text   -- null = yes, else the refusal code
language plpgsql stable security definer set search_path to '' as $f$
declare c pb_msg.chats; o uuid;
begin
  select * into c from pb_msg.chats where id = p_chat;
  if not found then return 'pb:not_found'; end if;
  if pb_msg.can_read(p_chat, p_uid) is null then return 'pb:not_in_chat'; end if;
  if c.closed_at is not null then return 'pb:chat_closed'; end if;
  if not pb_msg.co_active(c.company_id) then return 'pb:company_inactive'; end if;
  if c.kind = 'dm' then
    o := case when c.dm_a = p_uid then c.dm_b else c.dm_a end;
    if pb_msg.role_in(o, c.company_id) is null then return 'pb:other_left'; end if;
  end if;
  return null;
end $f$;

create or replace function pb_msg.log(p_chat uuid, p_by uuid, p_what text, p_target uuid, p_old jsonb, p_new jsonb) returns void
language sql security definer set search_path to '' as $f$
  insert into pb_msg.chat_log (chat_id, company_id, by_user, what, target_user, old_value, new_value)
  select p_chat, c.company_id, p_by, p_what, p_target, p_old, p_new from pb_msg.chats c where c.id = p_chat
$f$;

create or replace function pb_msg.me(p_expect uuid) returns uuid
language plpgsql stable security definer set search_path to '' as $f$
declare v uuid := auth.uid();
begin
  if v is null then raise exception 'pb:signed_out'; end if;
  if p_expect is null or v <> p_expect then raise exception 'pb:wrong_account'; end if;
  return v;
end $f$;

-- one chat as the app shows it in the list / header
create or replace function pb_msg.chat_json(p_chat uuid, p_uid uuid) returns jsonb
language plpgsql stable security definer set search_path to '' as $f$
declare c pb_msg.chats; s bigint; o uuid; v_last pb_msg.messages; v_read bigint; v_unread integer; v_title text; v_proj text;
begin
  select * into c from pb_msg.chats where id = p_chat;
  s := pb_msg.can_read(p_chat, p_uid);
  if not found or s is null then return null; end if;
  select * into v_last from pb_msg.messages m where m.chat_id = p_chat and m.seq > s order by m.seq desc limit 1;
  select r.last_seq into v_read from pb_msg.reads r where r.chat_id = p_chat and r.user_id = p_uid;
  select count(*) into v_unread from pb_msg.messages m where m.chat_id = p_chat and m.seq > greatest(s, coalesce(v_read, 0)) and m.author <> p_uid and m.deleted_at is null;
  if c.kind = 'dm' then o := case when c.dm_a = p_uid then c.dm_b else c.dm_a end; v_title := pb_msg.name_of(c.company_id, o);
  else
    v_title := 'Job ' || coalesce(nullif(c.job_number, ''), c.job_key);
    begin select ji.project_name into v_proj from pb_prod.job_info ji where ji.company_id = c.company_id and ji.job_key = c.job_key; exception when others then v_proj := null; end;
  end if;
  return jsonb_build_object('id', c.id, 'kind', c.kind, 'job_number', c.job_number, 'job_key', c.job_key, 'title', v_title, 'project', v_proj,
    'other', o, 'other_in', case when c.kind = 'dm' then pb_msg.role_in(o, c.company_id) is not null end,
    'last_seq', c.last_seq, 'last_at', c.last_at, 'closed', c.closed_at is not null, 'unread', v_unread, 'read_seq', coalesce(v_read, 0),
    'muted', exists (select 1 from pb_msg.mutes x where x.chat_id = p_chat and x.user_id = p_uid),
    'include_pipelayers', c.include_pipelayers, 'pipelayer_history', c.pipelayer_history, 'from_seq', s, 'admin', pb_msg.is_admin(p_chat, p_uid),
    'last', case when v_last.id is null then null else jsonb_build_object('seq', v_last.seq, 'at', v_last.created_at, 'author_name', v_last.author_name, 'mine', v_last.author = p_uid,
       'deleted', v_last.deleted_at is not null, 'photos', jsonb_array_length(v_last.photos),
       'preview', case when v_last.deleted_at is not null then null else left(regexp_replace(coalesce(v_last.body, ''), '\s+', ' ', 'g'), 60) end) end);
end $f$;

create or replace function pb_msg.msg_json(m pb_msg.messages, p_uid uuid) returns jsonb
language sql stable security definer set search_path to '' as $f$
  select jsonb_build_object('id', m.id, 'seq', m.seq, 'client_id', m.client_id, 'author', m.author, 'author_name', m.author_name, 'mine', m.author = p_uid,
    'at', m.created_at, 'phone_at', m.phone_at, 'edited', m.edited_at is not null, 'version', m.version,
    'deleted', m.deleted_at is not null,
    'body', case when m.deleted_at is null then m.body end,
    'photos', case when m.deleted_at is null then m.photos else '[]'::jsonb end)
$f$;

-- ============================ push (existing pb_push system) ============================
do $p$ begin
  if to_regclass('pb_push.outbox') is not null then
    alter table pb_push.outbox drop constraint if exists pb_push_out_type;
    alter table pb_push.outbox add constraint pb_push_out_type check (type = any (array['runs_waiting', 'mgmt_report', 'test', 'crew_production', 'run_end_ask',
      'material_alert', 'crew_nudge', 'permit_closed', 'permit_due', 'schedule', 'delays', 'locates', 'safety', 'plan_change', 'run_back', 'weather',
      'emergency', 'inspection', 'daily_missing', 'message']));
  end if;
end $p$;

create or replace function pb_msg.tz_for(p_chat uuid, p_uid uuid) returns text
language plpgsql stable security definer set search_path to '' as $f$
declare c pb_msg.chats; v text;
begin
  select * into c from pb_msg.chats where id = p_chat;
  if c.kind = 'dm' then begin select pp.tz into v from pb_prod.push_prefs pp where pp.user_id = p_uid; exception when others then v := null; end; end if;
  if v is null then begin select s.tz into v from pb_pm.settings s where s.company_id = c.company_id; exception when others then v := null; end; end if;
  v := coalesce(nullif(v, ''), 'America/Chicago');
  begin perform now() at time zone v; exception when others then v := 'America/Chicago'; end;
  return v;
end $f$;
-- when an alert to this person may go out: now, or the end of their quiet hours (local time of the job)
create or replace function pb_msg.send_at(p_chat uuid, p_uid uuid, p_now timestamptz default now()) returns timestamptz
language plpgsql stable security definer set search_path to '' as $f$
declare pr pb_msg.person_prefs; z text; loc timestamp; t time; quiet boolean;
begin
  select * into pr from pb_msg.person_prefs where user_id = p_uid;
  if not found then pr.quiet_on := true; pr.quiet_from := '19:00'; pr.quiet_to := '06:00'; end if;
  if not pr.quiet_on or pr.quiet_from = pr.quiet_to then return p_now; end if;
  z := pb_msg.tz_for(p_chat, p_uid);
  loc := p_now at time zone z; t := loc::time;
  quiet := case when pr.quiet_from > pr.quiet_to then t >= pr.quiet_from or t < pr.quiet_to else t >= pr.quiet_from and t < pr.quiet_to end;
  if not quiet then return p_now; end if;
  return ((case when t < pr.quiet_to then loc::date else loc::date + 1 end) + pr.quiet_to) at time zone z;
end $f$;

create or replace function pb_msg.notify(p_msg uuid) returns integer
language plpgsql security definer set search_path to '' as $f$
declare m pb_msg.messages; c pb_msg.chats; u uuid; s bigint; pr pb_msg.person_prefs; pend pb_msg.push_pending; v_at timestamptz;
  v_title text; v_body text; v_prev text; v_id uuid; v_n integer := 0; v_kick boolean := false; v_short text;
begin
  select * into m from pb_msg.messages where id = p_msg;
  select * into c from pb_msg.chats where id = m.chat_id;
  if to_regclass('pb_push.outbox') is null then return 0; end if;
  v_short := split_part(coalesce(m.author_name, 'Someone'), ' ', 1);
  v_prev := case when coalesce(btrim(m.body), '') = '' then case when jsonb_array_length(m.photos) > 1 then jsonb_array_length(m.photos) || ' photos' else 'Photo' end
                 else left(regexp_replace(btrim(m.body), '\s+', ' ', 'g'), 60) || case when length(regexp_replace(btrim(m.body), '\s+', ' ', 'g')) > 60 then '…' else '' end end;
  for u in select p.user_id from pb_msg.people p where p.chat_id = c.id and p.state = 'in' and p.user_id <> m.author loop
    s := pb_msg.can_read(c.id, u);
    if s is null or m.seq <= s then continue; end if;
    if exists (select 1 from pb_msg.mutes x where x.chat_id = c.id and x.user_id = u) then continue; end if;
    select * into pr from pb_msg.person_prefs where user_id = u;
    if found and not pr.push then continue; end if;
    if not found then pr.words := true; end if;
    v_at := pb_msg.send_at(c.id, u);
    if pr.words then
      v_title := left(case when c.kind = 'job' then 'Job ' || coalesce(nullif(c.job_number, ''), c.job_key) || ' · ' || v_short else coalesce(m.author_name, 'Message') end, 80);
      v_body := v_prev;
    else
      v_title := 'Messages';
      v_body := left(case when c.kind = 'job' then 'New message in Job ' || coalesce(nullif(c.job_number, ''), c.job_key) || ' from ' || v_short else 'New message from ' || v_short end, 180);
    end if;
    select * into pend from pb_msg.push_pending where chat_id = c.id and user_id = u;
    v_id := null;
    if found then -- fold into the alert still waiting (not sent, not being sent)
      update pb_push.outbox o set title = v_title,
          body = left(case when pr.words then (pend.n + 1) || ' new messages. Last: ' || v_prev
                           else (pend.n + 1) || ' new messages' || case when c.kind = 'job' then ' in Job ' || coalesce(nullif(c.job_number, ''), c.job_key) else ' from ' || v_short end end, 180),
          next_attempt_at = least(o.next_attempt_at, v_at)
        where o.id = pend.outbox_id and o.sent_at is null and o.given_up_at is null and o.claimed_at is null
        returning o.id into v_id;
      if v_id is not null then update pb_msg.push_pending set n = n + 1, last_msg = m.id where chat_id = c.id and user_id = u; end if;
    end if;
    if v_id is null then
      insert into pb_push.outbox (user_id, type, title, body, url, dedupe_key, next_attempt_at)
        values (u, 'message', v_title, v_body, '#/messages/' || c.id::text, 'msg:' || m.id::text || ':' || u::text, v_at)
        on conflict (dedupe_key) do nothing returning id into v_id;
      if v_id is not null then
        insert into pb_msg.push_pending (chat_id, user_id, outbox_id, n, last_msg) values (c.id, u, v_id, 1, m.id)
          on conflict (chat_id, user_id) do update set outbox_id = excluded.outbox_id, n = 1, last_msg = excluded.last_msg;
      end if;
    end if;
    if v_id is not null then v_n := v_n + 1; if v_at <= now() then v_kick := true; end if; end if;
  end loop;
  if v_kick and coalesce(current_setting('pb_msg.no_kick', true), '') <> 'on' and to_regprocedure('pb_push.kick()') is not null then
    begin execute 'select pb_push.kick()'; exception when others then null; end;
  end if;
  return v_n;
end $f$;
-- the person has seen the chat: a waiting alert for it is cancelled
create or replace function pb_msg.cancel_alert(p_chat uuid, p_uid uuid) returns void
language plpgsql security definer set search_path to '' as $f$
declare pend pb_msg.push_pending;
begin
  select * into pend from pb_msg.push_pending where chat_id = p_chat and user_id = p_uid;
  if not found then return; end if;
  update pb_push.outbox set given_up_at = now(), last_error = 'read' where id = pend.outbox_id and sent_at is null and given_up_at is null and claimed_at is null;
  delete from pb_msg.push_pending where chat_id = p_chat and user_id = p_uid;
end $f$;

-- ============================ app functions (public) ============================
create or replace function public.pb_msg_list(p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); co uuid; r text; ch record; j jsonb; v_out jsonb := '[]'::jsonb; pr pb_msg.person_prefs; ret text;
begin
  co := pb_msg.my_co(v); r := pb_msg.role_in(v, co);
  if co is null or r is null then return jsonb_build_object('ok', true, 'member', false, 'chats', '[]'::jsonb, 'server_at', now()); end if;
  for ch in select c.id, c.kind from pb_msg.chats c where c.company_id = co and (c.kind = 'job' or v in (c.dm_a, c.dm_b))
            order by c.last_at desc nulls last, c.created_at desc limit 300 loop
    if ch.kind = 'job' and r = 'pipelayer' then perform pb_msg.sync_one(ch.id, v); end if;   -- a pipelayer newly on the crew is added now
    j := pb_msg.chat_json(ch.id, v);
    if j is not null then v_out := v_out || jsonb_build_array(j); end if;
  end loop;
  select * into pr from pb_msg.person_prefs where user_id = v;
  select s.retention into ret from pb_msg.company_settings s where s.company_id = co;
  return jsonb_build_object('ok', true, 'member', true, 'me', jsonb_build_object('uid', v, 'role', r, 'company_id', co, 'name', pb_msg.name_of(co, v), 'is_owner', pb_msg.is_owner(v, co),
      'can_retention', pb_msg.role_in(v, co) = 'office' and (exists (select 1 from public.companies c where c.id = co and c.owner_user_id = v) or exists (select 1 from pb_reports.managers g where g.company_id = co and g.user_id = v))),
    'prefs', jsonb_build_object('push', coalesce(pr.push, true), 'words', coalesce(pr.words, true), 'quiet_on', coalesce(pr.quiet_on, true),
      'quiet_from', to_char(coalesce(pr.quiet_from, '19:00'::time), 'HH24:MI'), 'quiet_to', to_char(coalesce(pr.quiet_to, '06:00'::time), 'HH24:MI')),
    'retention', coalesce(ret, 'forever'), 'chats', v_out, 'server_at', now());
end $f$;

create or replace function public.pb_msg_people(p_expect_uid uuid) returns jsonb
language plpgsql stable security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); co uuid := pb_msg.my_co(v);
begin
  if pb_msg.role_in(v, co) is null then raise exception 'pb:not_company_member'; end if;
  return jsonb_build_object('ok', true, 'people', coalesce((select jsonb_agg(jsonb_build_object('uid', x.u, 'name', pb_msg.name_of(co, x.u), 'role', pb_msg.role_in(x.u, co)) order by pb_msg.name_of(co, x.u))
    from (select m.user_id u from public.company_members m where m.company_id = co union select c.owner_user_id from public.companies c where c.id = co) x where x.u <> v), '[]'::jsonb));
end $f$;

create or replace function public.pb_msg_open_job(p_job_number text, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); co uuid := pb_msg.my_co(v); r text; jk text := pb_prod.job_key(p_job_number); v_id uuid; ok boolean;
begin
  r := pb_msg.role_in(v, co);
  if r is null then raise exception 'pb:not_company_member'; end if;
  if jk = '' then raise exception 'pb:bad_job'; end if;
  select c.id into v_id from pb_msg.chats c where c.company_id = co and c.kind = 'job' and c.job_key = jk;
  if v_id is null then
    -- only someone who would be in it may start it (pipelayers are never in a new chat: the switch starts off)
    ok := pb_msg.jq(co, jk, false, null, v) is not null;
    if not ok then raise exception 'pb:not_in_chat'; end if;
    if not pb_msg.co_active(co) then raise exception 'pb:company_inactive'; end if;
    if (select count(*) from pb_msg.chats c where c.company_id = co) >= 5000 then raise exception 'pb:quota'; end if;
    insert into pb_msg.chats (company_id, kind, job_key, job_number, created_by) values (co, 'job', jk, left(btrim(p_job_number), 60), v)
      on conflict do nothing returning chats.id into v_id;
    if v_id is null then select c.id into v_id from pb_msg.chats c where c.company_id = co and c.kind = 'job' and c.job_key = jk;
    else
      insert into pb_msg.people (chat_id, user_id, state, how) values (v_id, v, 'in', 'creator') on conflict do nothing;
      perform pb_msg.log(v_id, v, 'started', null, null, jsonb_build_object('job_number', left(btrim(p_job_number), 60)));
    end if;
  end if;
  perform pb_msg.sync_one(v_id, v);
  if pb_msg.can_read(v_id, v) is null then raise exception 'pb:not_in_chat'; end if;
  return jsonb_build_object('ok', true, 'chat', pb_msg.chat_json(v_id, v));
end $f$;

create or replace function public.pb_msg_open_dm(p_user uuid, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); co uuid := pb_msg.my_co(v); a uuid; b uuid; v_id uuid;
begin
  if pb_msg.role_in(v, co) is null then raise exception 'pb:not_company_member'; end if;
  if p_user is null or p_user = v or pb_msg.role_in(p_user, co) is null then raise exception 'pb:not_in_chat'; end if;  -- the other person must be in the same company now
  a := least(v, p_user); b := greatest(v, p_user);
  select c.id into v_id from pb_msg.chats c where c.company_id = co and c.kind = 'dm' and c.dm_a = a and c.dm_b = b;
  if v_id is null then
    if not pb_msg.co_active(co) then raise exception 'pb:company_inactive'; end if;
    insert into pb_msg.chats (company_id, kind, dm_a, dm_b, created_by) values (co, 'dm', a, b, v) on conflict do nothing returning chats.id into v_id;
    if v_id is null then select c.id into v_id from pb_msg.chats c where c.company_id = co and c.kind = 'dm' and c.dm_a = a and c.dm_b = b; end if;
  end if;
  perform pb_msg.sync_roster(v_id);
  return jsonb_build_object('ok', true, 'chat', pb_msg.chat_json(v_id, v));
end $f$;

create or replace function public.pb_msg_fetch(p_chat uuid, p_after_seq bigint, p_before_seq bigint, p_limit integer, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); s bigint; lim integer := least(greatest(coalesce(p_limit, 100), 1), 200); v_out jsonb;
begin
  perform pb_msg.sync_one(p_chat, v);
  s := pb_msg.can_read(p_chat, v);
  if s is null then raise exception 'pb:not_in_chat'; end if;
  select coalesce(jsonb_agg(pb_msg.msg_json(x.mm, v) order by (x.mm).seq), '[]'::jsonb) into v_out from (
    select m as mm from pb_msg.messages m where m.chat_id = p_chat and m.seq > greatest(s, coalesce(p_after_seq, -1))
      and (p_before_seq is null or m.seq < p_before_seq)
    order by case when p_before_seq is null and p_after_seq is null then -m.seq when p_before_seq is not null then -m.seq else m.seq end limit lim) x;
  return jsonb_build_object('ok', true, 'chat', pb_msg.chat_json(p_chat, v), 'messages', v_out, 'can_post', pb_msg.can_post(p_chat, v) is null,
    'why_not', pb_msg.can_post(p_chat, v), 'server_at', now());
end $f$;

create or replace function public.pb_msg_send(p_chat uuid, p_client_id text, p_body text, p_photos jsonb, p_phone_at timestamptz, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); c pb_msg.chats; why text; m pb_msg.messages; b text := nullif(btrim(coalesce(p_body, '')), ''); ph jsonb := coalesce(p_photos, '[]'::jsonb);
  e jsonb; v_path text; v_seq bigint; i integer := 0; v_ph jsonb := '[]'::jsonb; v_size bigint;
begin
  select * into m from pb_msg.messages x where x.chat_id = p_chat and x.author = v and x.client_id = p_client_id;
  if found then return jsonb_build_object('ok', true, 'again', true, 'message', pb_msg.msg_json(m, v)); end if;   -- the phone sent it twice: same answer
  perform pb_msg.sync_one(p_chat, v);
  why := pb_msg.can_post(p_chat, v);
  if why is not null then raise exception '%', why; end if;
  if p_client_id is null or p_client_id !~ '^[A-Za-z0-9_-]{8,64}$' then raise exception 'pb:bad_id'; end if;
  if b is not null and length(b) > 4000 then raise exception 'pb:too_long'; end if;
  if jsonb_typeof(ph) <> 'array' or jsonb_array_length(ph) > 6 then raise exception 'pb:bad_photo'; end if;
  if b is null and jsonb_array_length(ph) = 0 then raise exception 'pb:empty'; end if;
  if (select count(*) from pb_msg.messages x where x.author = v and x.created_at > now() - interval '1 day') >= 500 then raise exception 'pb:quota'; end if;
  select * into c from pb_msg.chats where id = p_chat for update;
  for e in select * from jsonb_array_elements(ph) loop
    i := i + 1;
    v_path := e->>'path';
    if v_path is null or v_path !~ ('^' || c.company_id::text || '/' || c.id::text || '/' || v::text || '/' || p_client_id || '-[1-6]\.jpg$') then raise exception 'pb:bad_photo'; end if;
    select (o.metadata->>'size')::bigint into v_size from storage.objects o where o.bucket_id = 'msg-photos' and o.name = v_path and o.owner_id = v::text;
    if not found then raise exception 'pb:photo_missing'; end if;                       -- upload first, then send
    v_ph := v_ph || jsonb_build_array(jsonb_build_object('path', v_path, 'bytes', coalesce(v_size, (e->>'bytes')::bigint),
      'w', least(greatest(coalesce((e->>'w')::int, 0), 0), 4000), 'h', least(greatest(coalesce((e->>'h')::int, 0), 0), 4000),
      'sha256', case when coalesce(e->>'sha256', '') ~ '^[0-9a-f]{64}$' then e->>'sha256' end));
  end loop;
  update pb_msg.chats set last_seq = last_seq + 1, last_at = now() where id = p_chat returning last_seq into v_seq;
  insert into pb_msg.messages (chat_id, company_id, seq, author, author_name, client_id, body, photos, phone_at)
    values (p_chat, c.company_id, v_seq, v, pb_msg.name_of(c.company_id, v), p_client_id, b, v_ph,
            case when p_phone_at between now() - interval '30 days' and now() + interval '5 minutes' then p_phone_at end)
    returning * into m;
  insert into pb_msg.reads (chat_id, user_id, last_seq) values (p_chat, v, v_seq) on conflict (chat_id, user_id) do update set last_seq = greatest(pb_msg.reads.last_seq, excluded.last_seq), at = now();
  perform pb_msg.sync_roster(p_chat);
  perform pb_msg.notify(m.id);
  return jsonb_build_object('ok', true, 'message', pb_msg.msg_json(m, v));
end $f$;

create or replace function public.pb_msg_edit(p_message uuid, p_body text, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); m pb_msg.messages; why text; b text := nullif(btrim(coalesce(p_body, '')), '');
begin
  select * into m from pb_msg.messages where id = p_message for update;
  if not found or pb_msg.can_read(m.chat_id, v) is null then raise exception 'pb:not_found'; end if;
  if m.author <> v then raise exception 'pb:not_yours'; end if;
  if m.deleted_at is not null then raise exception 'pb:deleted'; end if;
  if m.created_at < now() - interval '24 hours' then raise exception 'pb:too_late'; end if;
  why := pb_msg.can_post(m.chat_id, v); if why is not null then raise exception '%', why; end if;
  if b is null and jsonb_array_length(m.photos) = 0 then raise exception 'pb:empty'; end if;
  if b is not null and length(b) > 4000 then raise exception 'pb:too_long'; end if;
  if b is not distinct from m.body then return jsonb_build_object('ok', true, 'same', true, 'message', pb_msg.msg_json(m, v)); end if;
  update pb_msg.messages set body = b, edited_at = now(), version = version + 1 where id = p_message returning * into m;
  return jsonb_build_object('ok', true, 'message', pb_msg.msg_json(m, v));
end $f$;

create or replace function public.pb_msg_delete(p_message uuid, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); m pb_msg.messages; q text; pend pb_msg.push_pending;
begin
  select * into m from pb_msg.messages where id = p_message for update;
  if not found or pb_msg.can_read(m.chat_id, v) is null then raise exception 'pb:not_found'; end if;
  q := pb_msg.qual(m.chat_id, v);
  if m.author <> v and coalesce(q not in ('office', 'pm'), true) then raise exception 'pb:not_yours'; end if;
  if m.deleted_at is not null then return jsonb_build_object('ok', true, 'again', true, 'message', pb_msg.msg_json(m, v)); end if;
  update pb_msg.messages set deleted_at = now(), deleted_by = v, version = version + 1 where id = p_message returning * into m;
  if m.author <> v then perform pb_msg.log(m.chat_id, v, 'message_deleted', m.author, jsonb_build_object('seq', m.seq), null); end if;
  for pend in select * from pb_msg.push_pending where chat_id = m.chat_id and last_msg = m.id and n = 1 loop   -- its alert, not out yet: cancelled
    perform pb_msg.cancel_alert(m.chat_id, pend.user_id);
  end loop;
  return jsonb_build_object('ok', true, 'message', pb_msg.msg_json(m, v));
end $f$;

create or replace function public.pb_msg_read(p_chat uuid, p_seq bigint, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); c pb_msg.chats;
begin
  if pb_msg.can_read(p_chat, v) is null then raise exception 'pb:not_in_chat'; end if;
  select * into c from pb_msg.chats where id = p_chat;
  insert into pb_msg.reads (chat_id, user_id, last_seq) values (p_chat, v, least(greatest(coalesce(p_seq, 0), 0), c.last_seq))
    on conflict (chat_id, user_id) do update set last_seq = greatest(pb_msg.reads.last_seq, excluded.last_seq), at = now();
  perform pb_msg.cancel_alert(p_chat, v);
  return jsonb_build_object('ok', true);
end $f$;

create or replace function public.pb_msg_info(p_chat uuid, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); c pb_msg.chats; q text; ppl jsonb; lg jsonb; ar jsonb;
begin
  perform pb_msg.sync_one(p_chat, v);
  if pb_msg.can_read(p_chat, v) is null then raise exception 'pb:not_in_chat'; end if;
  select * into c from pb_msg.chats where id = p_chat;
  q := pb_msg.qual(p_chat, v);
  perform pb_msg.sync_roster(p_chat);
  select coalesce(jsonb_agg(jsonb_build_object('uid', p.user_id, 'name', pb_msg.name_of(c.company_id, p.user_id), 'role', pb_msg.role_in(p.user_id, c.company_id),
      'state', case when pb_msg.can_read(p_chat, p.user_id) is not null then 'in' when p.state = 'out' then 'out' else 'not_now' end,
      'since', p.since, 'how', p.how) order by (pb_msg.can_read(p_chat, p.user_id) is null), pb_msg.role_in(p.user_id, c.company_id), pb_msg.name_of(c.company_id, p.user_id)), '[]'::jsonb)
    into ppl from pb_msg.people p where p.chat_id = p_chat and pb_msg.role_in(p.user_id, c.company_id) is not null;
  select coalesce(jsonb_agg(jsonb_build_object('at', l.at, 'by', pb_msg.name_of(c.company_id, l.by_user), 'what', l.what,
      'target', case when l.target_user is not null then pb_msg.name_of(c.company_id, l.target_user) end, 'old', l.old_value, 'new', l.new_value) order by l.at desc), '[]'::jsonb)
    into lg from (select * from pb_msg.chat_log l where l.chat_id = p_chat order by l.at desc limit 50) l;
  if (c.kind = 'job' and q in ('office', 'pm')) or (c.kind = 'dm' and pb_msg.is_owner(v, c.company_id)) then
    select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'state', a.state, 'reason', a.reason, 'at', coalesce(a.done_at, a.requested_at), 'files', a.files, 'bytes', a.bytes,
        'messages', a.messages, 'photos', a.photos) order by a.requested_at desc), '[]'::jsonb) into ar
      from (select * from pb_msg.archives a where a.chat_id = p_chat and a.state <> 'purged' order by a.requested_at desc limit 20) a;
  end if;
  return jsonb_build_object('ok', true, 'chat', pb_msg.chat_json(p_chat, v), 'can_manage', q in ('office', 'pm') and c.kind = 'job', 'office', q in ('office', 'pm'),
    'rule', case when c.kind = 'job' then pb_msg.rule(c.company_id, c.job_key) end,
    'people', ppl, 'log', lg, 'archives', ar, 'settings_ver', c.settings_ver, 'closed_at', c.closed_at, 'server_at', now());
end $f$;

create or replace function public.pb_msg_set(p_chat uuid, p_include_pipelayers boolean, p_pipelayer_history text, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); c pb_msg.chats; h text := coalesce(p_pipelayer_history, 'from_added');
begin
  select * into c from pb_msg.chats where id = p_chat for update;
  if not found or c.kind <> 'job' or not pb_msg.is_admin(p_chat, v) then raise exception 'pb:not_office'; end if;
  if h not in ('from_added', 'all') or p_include_pipelayers is null then raise exception 'pb:bad_value'; end if;
  if p_include_pipelayers is distinct from c.include_pipelayers then
    perform pb_msg.log(p_chat, v, 'include_pipelayers', null, to_jsonb(c.include_pipelayers), to_jsonb(p_include_pipelayers));
  end if;
  if h is distinct from c.pipelayer_history then
    perform pb_msg.log(p_chat, v, 'pipelayer_history', null, to_jsonb(c.pipelayer_history), to_jsonb(h));
  end if;
  update pb_msg.chats set include_pipelayers = p_include_pipelayers, pipelayer_history = h, settings_ver = settings_ver + 1 where id = p_chat;
  if not p_include_pipelayers then -- pipelayers lose access now; turning it back on adds them again from that moment
    update pb_msg.people p set state = 'off', changed_by = v, changed_at = now()
      where p.chat_id = p_chat and p.state = 'in' and pb_msg.role_in(p.user_id, c.company_id) = 'pipelayer';
  else
    perform pb_msg.sync_roster(p_chat);
  end if;
  return jsonb_build_object('ok', true, 'chat', pb_msg.chat_json(p_chat, v));
end $f$;

create or replace function public.pb_msg_person(p_chat uuid, p_user uuid, p_in boolean, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); c pb_msg.chats; r text; cur text;
begin
  select * into c from pb_msg.chats where id = p_chat for update;
  if not found or c.kind <> 'job' or not pb_msg.is_admin(p_chat, v) then raise exception 'pb:not_office'; end if;
  r := pb_msg.role_in(p_user, c.company_id);
  if r is null then raise exception 'pb:not_company_member'; end if;   -- never anyone outside the company
  if r = 'office' then raise exception 'pb:office_always_in'; end if;   -- (a PM/super can be added to or taken off a job chat)
  if p_in is null then raise exception 'pb:bad_value'; end if;
  select p.state into cur from pb_msg.people p where p.chat_id = p_chat and p.user_id = p_user;
  insert into pb_msg.people (chat_id, user_id, state, how, since, since_seq, changed_by)
    values (p_chat, p_user, case when p_in then 'in' else 'out' end, 'office', now(), c.last_seq, v)
  on conflict (chat_id, user_id) do update set state = excluded.state, how = 'office', changed_by = v, changed_at = now(),
    since = case when pb_msg.people.state = 'in' then pb_msg.people.since else now() end,
    since_seq = case when pb_msg.people.state = 'in' then pb_msg.people.since_seq else c.last_seq end;
  perform pb_msg.log(p_chat, v, case when p_in then 'person_added' else 'person_removed' end, p_user, to_jsonb(cur), to_jsonb(case when p_in then 'in' else 'out' end));
  return jsonb_build_object('ok', true, 'note', case when p_in and r = 'pipelayer' and not c.include_pipelayers then 'pipelayers_off' end);
end $f$;

create or replace function public.pb_msg_mute(p_chat uuid, p_muted boolean, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid);
begin
  if pb_msg.can_read(p_chat, v) is null then raise exception 'pb:not_in_chat'; end if;
  if p_muted then insert into pb_msg.mutes (chat_id, user_id) values (p_chat, v) on conflict do nothing; perform pb_msg.cancel_alert(p_chat, v);
  else delete from pb_msg.mutes where chat_id = p_chat and user_id = v; end if;
  return jsonb_build_object('ok', true, 'muted', coalesce(p_muted, false));
end $f$;

create or replace function public.pb_msg_prefs_set(p_push boolean, p_words boolean, p_quiet_on boolean, p_quiet_from text, p_quiet_to text, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); f time; t time;
begin
  if coalesce(p_quiet_from, '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or coalesce(p_quiet_to, '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception 'pb:bad_value'; end if;
  f := p_quiet_from::time; t := p_quiet_to::time;
  insert into pb_msg.person_prefs (user_id, push, words, quiet_on, quiet_from, quiet_to) values (v, coalesce(p_push, true), coalesce(p_words, true), coalesce(p_quiet_on, true), f, t)
    on conflict (user_id) do update set push = excluded.push, words = excluded.words, quiet_on = excluded.quiet_on, quiet_from = excluded.quiet_from, quiet_to = excluded.quiet_to, updated_at = now();
  return jsonb_build_object('ok', true);
end $f$;

create or replace function public.pb_msg_company_set(p_retention text, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); co uuid := pb_msg.my_co(v); cur text;
begin
  -- the company account and its managers (not PMs/supers, not crews): how long the company keeps its records is theirs
  if co is null or not (exists (select 1 from public.companies c where c.id = co and c.owner_user_id = v)
                        or (pb_msg.role_in(v, co) = 'office' and exists (select 1 from pb_reports.managers g where g.company_id = co and g.user_id = v))) then  -- (role 'office' = not a PM)
    raise exception 'pb:not_company_account';
  end if;
  if p_retention not in ('forever', '13m') then raise exception 'pb:bad_value'; end if;
  select s.retention into cur from pb_msg.company_settings s where s.company_id = co;
  insert into pb_msg.company_settings (company_id, retention, updated_by) values (co, p_retention, v)
    on conflict (company_id) do update set retention = excluded.retention, updated_by = v, updated_at = now();
  if coalesce(cur, 'forever') <> p_retention then
    insert into pb_msg.company_log (company_id, by_user, what, old_value, new_value) values (co, v, 'retention', to_jsonb(coalesce(cur, 'forever')), to_jsonb(p_retention));
  end if;
  return jsonb_build_object('ok', true, 'retention', p_retention);
end $f$;

create or replace function pb_msg.queue_archive(p_chat uuid, p_reason text, p_by uuid) returns uuid
language plpgsql security definer set search_path to '' as $f$
declare c pb_msg.chats; v_id uuid;
begin
  select * into c from pb_msg.chats x where x.id = p_chat;
  select a.id into v_id from pb_msg.archives a where a.chat_id = p_chat and a.state in ('queued', 'working');
  if v_id is not null then return v_id; end if;                    -- one at a time per chat
  insert into pb_msg.archives (chat_id, company_id, reason, requested_by) values (p_chat, c.company_id, p_reason, p_by) returning archives.id into v_id;
  perform pb_msg.log(p_chat, p_by, 'archive_requested', null, null, jsonb_build_object('reason', p_reason));
  return v_id;
end $f$;
-- wake the archive writer (same pattern and secret as pb_push.kick); skipped in tests
create or replace function pb_msg.kick_archive() returns void
language plpgsql security definer set search_path to '' as $f$
declare v_secret text;
begin
  if coalesce(current_setting('pb_msg.no_kick', true), '') = 'on' then return; end if;
  begin
    execute 'select ds.decrypted_secret from vault.decrypted_secrets ds where ds.name = ''push_cron_secret'' limit 1' into v_secret;
    if v_secret is null or length(v_secret) < 16 then return; end if;
    execute 'select net.http_post(url := $1, body := ''{}''::jsonb, headers := jsonb_build_object(''Content-Type'', ''application/json'', ''x-pb-push-secret'', $2), timeout_milliseconds := 8000)'
      using 'https://rogfassochneycezecxa.supabase.co/functions/v1/msg-archive', v_secret;
  exception when others then raise log 'pb_msg.kick_archive: call not made (%)', sqlstate;
  end;
end $f$;

create or replace function public.pb_msg_close(p_chat uuid, p_closed boolean, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); c pb_msg.chats; a uuid;
begin
  select * into c from pb_msg.chats where id = p_chat for update;
  if not found or c.kind <> 'job' or not pb_msg.is_admin(p_chat, v) then raise exception 'pb:not_office'; end if;
  if p_closed and c.closed_at is null then
    update pb_msg.chats set closed_at = now(), closed_by = v where id = p_chat;
    perform pb_msg.log(p_chat, v, 'closed', null, null, null);
    a := pb_msg.queue_archive(p_chat, 'closed', v); perform pb_msg.kick_archive();
  elsif not p_closed and c.closed_at is not null then
    update pb_msg.chats set closed_at = null, closed_by = null where id = p_chat;
    perform pb_msg.log(p_chat, v, 'reopened', null, null, null);
  end if;
  return jsonb_build_object('ok', true, 'archive_id', a, 'chat', pb_msg.chat_json(p_chat, v));
end $f$;

create or replace function public.pb_msg_archive_request(p_chat uuid, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); a uuid;
begin
  if not (pb_msg.is_admin(p_chat, v) and exists (select 1 from pb_msg.chats c where c.id = p_chat and c.kind = 'job'))
     and not exists (select 1 from pb_msg.chats c where c.id = p_chat and c.kind = 'dm' and pb_msg.is_owner(v, c.company_id)) then
    raise exception 'pb:not_office';   -- a job chat: its office; a direct message: the company account only
  end if;
  if (select count(*) from pb_msg.archives x where x.chat_id = p_chat and x.requested_at > now() - interval '1 day') >= 5 then raise exception 'pb:quota'; end if;
  a := pb_msg.queue_archive(p_chat, 'office', v); perform pb_msg.kick_archive();
  return jsonb_build_object('ok', true, 'archive_id', a);
end $f$;

-- storage policy helpers: policies run as the caller (authenticated), so these are granted to authenticated
create or replace function public.pb_msg_photo_put_ok(p_name text) returns boolean
language plpgsql stable security definer set search_path to '' as $f$
declare a text[] := string_to_array(coalesce(p_name, ''), '/'); v uuid := auth.uid(); c pb_msg.chats; ok boolean;
begin
  if v is null or array_length(a, 1) <> 4 or a[3] <> v::text or a[4] !~ '^[A-Za-z0-9_-]{8,64}-[1-6]\.jpg$' then return false; end if;
  begin select * into c from pb_msg.chats x where x.id = a[2]::uuid and x.company_id = a[1]::uuid; exception when others then return false; end;
  if c.id is null or pb_msg.can_post(c.id, v) is not null then return false; end if;
  -- the existing daily photo cap (pb_billing.plan_limits photos_day; 150/day for this bucket) and a 2 GB per company ceiling
  if to_regprocedure('pb_billing.storage_room(uuid,text,integer)') is not null then
    execute 'select pb_billing.storage_room($1, ''msg-photos'', 150)' into ok using v;
    if not coalesce(ok, false) then return false; end if;
  end if;
  return (select coalesce(sum((o.metadata->>'size')::bigint), 0) from storage.objects o where o.bucket_id = 'msg-photos' and o.name like c.company_id::text || '/%') < 2147483648;
end $f$;
create or replace function public.pb_msg_photo_can_view(p_name text) returns boolean
language plpgsql stable security definer set search_path to '' as $f$
declare a text[] := string_to_array(coalesce(p_name, ''), '/'); v uuid := auth.uid(); s bigint; cid uuid;
begin
  if v is null or array_length(a, 1) <> 4 then return false; end if;
  begin cid := a[2]::uuid; exception when others then return false; end;
  s := pb_msg.can_read(cid, v);
  if s is null then return false; end if;
  return exists (select 1 from pb_msg.messages m where m.chat_id = cid and m.seq > s and m.deleted_at is null and m.photos @> jsonb_build_array(jsonb_build_object('path', p_name)));
end $f$;
-- may this person download this archive file now: the right person AND a logged download (pb_msg_archive_download) in the last 15 minutes
create or replace function public.pb_msg_archive_can_view(p_name text) returns boolean
language plpgsql stable security definer set search_path to '' as $f$
declare v uuid := auth.uid(); ar pb_msg.archives;
begin
  if v is null then return false; end if;
  select * into ar from pb_msg.archives a where a.state = 'done' and a.files @> jsonb_build_array(jsonb_build_object('path', p_name)) limit 1;
  if not found or pb_msg.my_co(v) is distinct from ar.company_id or not pb_msg.archive_ok(ar.chat_id, v) then return false; end if;
  return exists (select 1 from pb_msg.downloads d where d.path = p_name and d.by_user = v and d.at > now() - interval '15 minutes');
end $f$;
create or replace function pb_msg.archive_ok(p_chat uuid, p_uid uuid) returns boolean
language sql stable security definer set search_path to '' as $f$
  select exists (select 1 from pb_msg.chats c where c.id = p_chat and ((c.kind = 'job' and pb_msg.is_admin(c.id, p_uid)) or (c.kind = 'dm' and pb_msg.is_owner(p_uid, c.company_id))))
$f$;
-- the app asks before it downloads: logged (and shown in the chat's Changes), then the file opens for 15 minutes
create or replace function public.pb_msg_archive_download(p_archive uuid, p_path text, p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); ar pb_msg.archives;
begin
  select * into ar from pb_msg.archives a where a.id = p_archive and a.state = 'done' and a.files @> jsonb_build_array(jsonb_build_object('path', p_path));
  if not found or pb_msg.my_co(v) is distinct from ar.company_id or not pb_msg.archive_ok(ar.chat_id, v) then raise exception 'pb:not_office'; end if;
  insert into pb_msg.downloads (archive_id, chat_id, company_id, path, by_user) values (ar.id, ar.chat_id, ar.company_id, p_path, v);
  perform pb_msg.log(ar.chat_id, v, 'archive_downloaded', null, null, jsonb_build_object('archive', ar.id));
  return jsonb_build_object('ok', true, 'path', p_path);
end $f$;
-- the company account: every direct message in the company, as records (names, counts, archives; never the text)
create or replace function public.pb_msg_dm_records(p_expect_uid uuid) returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare v uuid := pb_msg.me(p_expect_uid); co uuid := pb_msg.my_co(v);
begin
  if co is null or not pb_msg.is_owner(v, co) then raise exception 'pb:not_company_account'; end if;
  return jsonb_build_object('ok', true, 'threads', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'a', pb_msg.name_of(co, c.dm_a), 'b', pb_msg.name_of(co, c.dm_b),
      'messages', (select count(*) from pb_msg.messages m where m.chat_id = c.id), 'last_at', c.last_at,
      'archives', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'state', a.state, 'at', coalesce(a.done_at, a.requested_at), 'files', a.files, 'bytes', a.bytes) order by a.requested_at desc)
                            from (select * from pb_msg.archives a where a.chat_id = c.id and a.state <> 'purged' order by a.requested_at desc limit 5) a), '[]'::jsonb))
      order by c.last_at desc nulls last) from (select * from pb_msg.chats c where c.company_id = co and c.kind = 'dm' and c.dm_a <> v and c.dm_b <> v order by c.last_at desc nulls last limit 300) c), '[]'::jsonb));
end $f$;

-- ============================ service (archive writer, retention) ============================
create or replace function public.pb_msg_svc_archive_next() returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare ar pb_msg.archives; c pb_msg.chats; ret text;
begin
  if not pb_push.is_service() then raise exception 'pb:not_allowed'; end if;
  update pb_msg.archives set state = 'queued' where state = 'working' and started_at < now() - interval '30 minutes';
  update pb_msg.archives set state = 'failed', note = 'gave up after 5 tries' where state = 'queued' and attempts >= 5;
  select * into ar from pb_msg.archives where state = 'queued' order by requested_at limit 1 for update skip locked;
  if not found then return jsonb_build_object('ok', true, 'archive', null); end if;
  update pb_msg.archives set state = 'working', started_at = now(), attempts = attempts + 1 where id = ar.id;
  select * into c from pb_msg.chats where id = ar.chat_id;
  select s.retention into ret from pb_msg.company_settings s where s.company_id = c.company_id;
  return jsonb_build_object('ok', true, 'archive', jsonb_build_object('id', ar.id, 'reason', ar.reason, 'requested_at', ar.requested_at),
    'retention', coalesce(ret, 'forever'), 'tz', pb_msg.tz_for(c.id, null),
    'company', jsonb_build_object('id', c.company_id, 'name', (select co.name from public.companies co where co.id = c.company_id)),
    'chat', jsonb_build_object('id', c.id, 'kind', c.kind, 'job_number', c.job_number, 'job_key', c.job_key, 'created_at', c.created_at, 'closed_at', c.closed_at,
       'include_pipelayers', c.include_pipelayers, 'pipelayer_history', c.pipelayer_history,
       'title', case when c.kind = 'job' then 'Job ' || coalesce(nullif(c.job_number, ''), c.job_key) else pb_msg.name_of(c.company_id, c.dm_a) || ' and ' || pb_msg.name_of(c.company_id, c.dm_b) end),
    'messages', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'seq', m.seq, 'author', m.author, 'author_name', m.author_name, 'at', m.created_at, 'phone_at', m.phone_at,
        'body', m.body, 'photos', m.photos, 'edited_at', m.edited_at, 'deleted_at', m.deleted_at, 'deleted_by', case when m.deleted_by is not null then pb_msg.name_of(c.company_id, m.deleted_by) end,
        'version', m.version) order by m.seq) from pb_msg.messages m where m.chat_id = c.id), '[]'::jsonb),
    'versions', coalesce((select jsonb_agg(jsonb_build_object('message_id', x.message_id, 'version', x.version, 'body', x.body, 'photos', x.photos, 'action', x.action,
        'by', case when x.by_user is not null then pb_msg.name_of(c.company_id, x.by_user) end, 'at', x.at) order by x.message_id, x.version) from pb_msg.message_versions x where x.chat_id = c.id), '[]'::jsonb),
    'people', coalesce((select jsonb_agg(jsonb_build_object('name', pb_msg.name_of(c.company_id, p.user_id), 'state', p.state, 'how', p.how, 'since', p.since)) from pb_msg.people p where p.chat_id = c.id), '[]'::jsonb),
    'log', coalesce((select jsonb_agg(jsonb_build_object('at', l.at, 'by', pb_msg.name_of(c.company_id, l.by_user), 'what', l.what,
        'target', case when l.target_user is not null then pb_msg.name_of(c.company_id, l.target_user) end, 'old', l.old_value, 'new', l.new_value) order by l.at) from pb_msg.chat_log l where l.chat_id = c.id), '[]'::jsonb),
    'server_at', now());
end $f$;
create or replace function public.pb_msg_svc_archive_done(p_id uuid, p_ok boolean, p_files jsonb, p_bytes bigint, p_messages integer, p_photos integer, p_upto_seq bigint, p_note text) returns jsonb
language plpgsql security definer set search_path to '' as $f$
begin
  if not pb_push.is_service() then raise exception 'pb:not_allowed'; end if;
  if p_ok then
    update pb_msg.archives set state = 'done', done_at = now(), files = coalesce(p_files, '[]'::jsonb), bytes = p_bytes, messages = p_messages, photos = p_photos, upto_seq = p_upto_seq, note = left(p_note, 300)
      where id = p_id and state = 'working';
  else
    update pb_msg.archives set state = 'queued', note = left(p_note, 300) where id = p_id and state = 'working';
  end if;
  return jsonb_build_object('ok', found);
end $f$;
-- files a 13-month company no longer keeps (the edge function deletes them through the Storage API, then calls pb_msg_svc_purged)
create or replace function public.pb_msg_svc_purge_list(p_limit integer default 200) returns jsonb
language plpgsql security definer set search_path to '' as $f$
begin
  if not pb_push.is_service() then raise exception 'pb:not_allowed'; end if;
  update pb_msg.archives a set state = 'purge' where a.state = 'done' and a.done_at < now() - interval '13 months'
    and exists (select 1 from pb_msg.company_settings s where s.company_id = a.company_id and s.retention = '13m');
  return jsonb_build_object('ok', true,
    'archives', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'files', a.files)) from (select * from pb_msg.archives a where a.state = 'purge' limit 50) a), '[]'::jsonb),
    'photos', coalesce((select jsonb_agg(o.name) from (select o.name from storage.objects o join pb_msg.company_settings s on s.retention = '13m' and o.name like s.company_id::text || '/%'
       where o.bucket_id = 'msg-photos' and o.created_at < now() - interval '13 months' limit greatest(1, least(coalesce(p_limit, 200), 1000))) o), '[]'::jsonb));
end $f$;
create or replace function public.pb_msg_svc_purged(p_archive_ids uuid[]) returns jsonb
language plpgsql security definer set search_path to '' as $f$
begin
  if not pb_push.is_service() then raise exception 'pb:not_allowed'; end if;
  update pb_msg.archives set state = 'purged', files = '[]'::jsonb, note = 'deleted after 13 months' where id = any (coalesce(p_archive_ids, '{}')) and state = 'purge';
  return jsonb_build_object('ok', true, 'n', (select count(*) from pb_msg.archives where id = any (coalesce(p_archive_ids, '{}')) and state = 'purged'));
end $f$;

-- daily (pg_cron): close idle job chats (and archive them), delete what a 13-month company no longer keeps, wake the writer
create or replace function pb_msg.sweep() returns jsonb
language plpgsql security definer set search_path to '' as $f$
declare c record; n_closed integer := 0; s record; v_m integer; v_v integer; v_any boolean;
begin
  for c in select x.id from pb_msg.chats x where x.kind = 'job' and x.closed_at is null and coalesce(x.last_at, x.created_at) < now() - interval '120 days' limit 500 loop
    update pb_msg.chats set closed_at = now() where id = c.id;
    perform pb_msg.log(c.id, null, 'closed', null, null, jsonb_build_object('why', 'no messages for 120 days'));
    perform pb_msg.queue_archive(c.id, 'idle', null);
    n_closed := n_closed + 1;
  end loop;
  perform set_config('pb.allow_record_delete', 'on', true);
  for s in select cs.company_id from pb_msg.company_settings cs where cs.retention = '13m' loop
    delete from pb_msg.message_versions x using pb_msg.messages m where x.message_id = m.id and m.company_id = s.company_id and m.created_at < now() - interval '13 months';
    get diagnostics v_v = row_count;
    delete from pb_msg.push_pending pp using pb_msg.messages m where pp.last_msg = m.id and m.company_id = s.company_id and m.created_at < now() - interval '13 months';
    delete from pb_msg.messages m where m.company_id = s.company_id and m.created_at < now() - interval '13 months';
    get diagnostics v_m = row_count;
    if v_m > 0 or v_v > 0 then insert into pb_msg.purge_log (company_id, messages, versions, before_at) values (s.company_id, v_m, v_v, now() - interval '13 months'); end if;
  end loop;
  perform set_config('pb.allow_record_delete', '', true);
  v_any := exists (select 1 from pb_msg.archives a where a.state in ('queued', 'purge'))
        or exists (select 1 from pb_msg.company_settings cs where cs.retention = '13m');
  if v_any then perform pb_msg.kick_archive(); end if;
  return jsonb_build_object('closed', n_closed);
end $f$;

-- ============================ grants ============================
do $g$ declare f record; begin
  for f in select p.oid::regprocedure sig, n.nspname from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where (n.nspname = 'pb_msg') or (n.nspname = 'public' and p.proname like 'pb\_msg\_%') loop
    execute format('revoke all on function %s from public', f.sig);
    execute format('revoke all on function %s from anon, authenticated', f.sig);
  end loop;
end $g$;
grant execute on function public.pb_msg_list(uuid), public.pb_msg_people(uuid), public.pb_msg_open_job(text, uuid), public.pb_msg_open_dm(uuid, uuid),
  public.pb_msg_fetch(uuid, bigint, bigint, integer, uuid), public.pb_msg_send(uuid, text, text, jsonb, timestamptz, uuid), public.pb_msg_edit(uuid, text, uuid),
  public.pb_msg_delete(uuid, uuid), public.pb_msg_read(uuid, bigint, uuid), public.pb_msg_info(uuid, uuid), public.pb_msg_set(uuid, boolean, text, uuid),
  public.pb_msg_person(uuid, uuid, boolean, uuid), public.pb_msg_mute(uuid, boolean, uuid), public.pb_msg_prefs_set(boolean, boolean, boolean, text, text, uuid),
  public.pb_msg_company_set(text, uuid), public.pb_msg_close(uuid, boolean, uuid), public.pb_msg_archive_request(uuid, uuid),
  public.pb_msg_photo_put_ok(text), public.pb_msg_photo_can_view(text), public.pb_msg_archive_can_view(text),
  public.pb_msg_archive_download(uuid, text, uuid), public.pb_msg_dm_records(uuid) to authenticated;
grant execute on function public.pb_msg_svc_archive_next(), public.pb_msg_svc_archive_done(uuid, boolean, jsonb, bigint, integer, integer, bigint, text),
  public.pb_msg_svc_purge_list(integer), public.pb_msg_svc_purged(uuid[]) to service_role;

-- daily sweep at 09:17 UTC (about 3-4 AM in the US: before the crews' day; quiet hours end at 6 by default)
do $c$ begin
  if to_regnamespace('cron') is not null then perform cron.schedule('pb_msg_sweep', '17 9 * * *', 'select pb_msg.sweep()'); end if;
exception when others then raise notice 'pb_msg: cron job not scheduled (%)', sqlerrm;
end $c$;

-- messaging_nov22 01 test. Every app call runs AS ROLE authenticated with that person's JWT claims (pg_temp.q), the
-- way PostgREST runs it, so a function authenticated can't execute fails here too. Ends with 'RESULT: ...' (rolled back).
create function pg_temp.q(p_user uuid, p_sql text) returns jsonb language plpgsql as $f$
declare r jsonb;
begin
  begin
    perform set_config('request.jwt.claims', jsonb_build_object('role', 'authenticated', 'sub', p_user, 'aal', 'aal1')::text, true);
    perform set_config('role', 'authenticated', true);
    execute p_sql into r;
    perform set_config('role', 'none', true);
    return coalesce(r, 'null'::jsonb);
  exception when others then
    return jsonb_build_object('err', sqlerrm);   -- (the role switch is undone with the failed sub-transaction)
  end;
end $f$;
create function pg_temp.svc(p_sql text) returns jsonb language plpgsql as $f$
declare r jsonb;
begin
  begin
    perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
    perform set_config('role', 'service_role', true);
    execute p_sql into r;
    perform set_config('role', 'none', true);
    return coalesce(r, 'null'::jsonb);
  exception when others then return jsonb_build_object('err', sqlerrm);
  end;
end $f$;
create function pg_temp.e(j jsonb) returns text language sql as $f$ select coalesce(j->>'err', case when (j->>'ok')::boolean then 'ok' else j::text end) $f$;

do $test$
declare
  pass integer; fail integer; fails text; notes text := ''; tag text := substr(md5(random()::text), 1, 8);
  o uuid := gen_random_uuid(); pm uuid := gen_random_uuid(); f1 uuid := gen_random_uuid(); f2 uuid := gen_random_uuid();
  p1 uuid := gen_random_uuid(); p2 uuid := gen_random_uuid(); p3 uuid := gen_random_uuid(); r uuid := gen_random_uuid();
  o2 uuid := gen_random_uuid(); x uuid := gen_random_uuid(); anyone uuid := gen_random_uuid();
  pm2 uuid := gen_random_uuid(); mgr uuid := gen_random_uuid(); wk uuid := gen_random_uuid(); jobb text; chb uuid; dm2 uuid; ar2 uuid; k2 text; item_f1 uuid := gen_random_uuid();
  c uuid := gen_random_uuid(); c2 uuid := gen_random_uuid();
  job text := 'MSGT-' || tag; j jsonb; ch uuid; ch2 uuid; dm uuid; m1 uuid; m2 uuid; m3 uuid; s text; n integer; t timestamptz; ar uuid; k text; old_m uuid;
begin
  create temp table t_chk (i serial, name text, ok boolean, got text) on commit drop;
  perform set_config('pb_msg.no_kick', 'on', true);
  insert into auth.users (id, email) select v, 'pbmsg-' || tag || '-' || row_number() over () || '@example.invalid' from unnest(array[o, pm, f1, f2, p1, p2, p3, r, o2, x, anyone, pm2, mgr, wk]) v;
  insert into public.companies (id, name, owner_user_id, status, plan) values (c, 'pbmsg ' || tag, o, 'active', 'paid'), (c2, 'pbmsg other ' || tag, o2, 'active', 'paid');
  insert into public.company_members (company_id, user_id, role) values (c, pm, 'pm'), (c, f1, 'foreman'), (c, f2, 'foreman'), (c, p1, 'pipelayer'),
    (c, p2, 'pipelayer'), (c, p3, 'pipelayer'), (c, r, 'foreman'), (c2, x, 'foreman'), (c, pm2, 'pm'), (c, mgr, 'foreman'), (c, wk, 'foreman');
  insert into pb_reports.managers (company_id, user_id) values (c, mgr);   -- a listed manager (office)
  jobb := 'MSGB-' || tag;
  -- ASSIGNED to the job (Tommy's rule): PM pm (pb_pm.job_pms), foremen f1 and r (inspection items, pb_daily.items).
  -- Filed work on it: f1, r, wk (foremen) and p2 (pipelayer); p1 is on f1's crew; f2, p3, pm2 nothing.
  -- Job B: nobody assigned; wk filed work on it (the fallback).
  insert into pb_pm.job_pms (company_id, job_key, job_number, user_id, assigned_by) values (c, lower(job), job, pm, o);
  insert into pb_daily.items (id, company_id, client_item_id, job_key, job_number, kind, foreman_uid, status, created_by) values
    (item_f1, c, 'msgt-' || tag || '-i1', lower(job), job, 'test', f1, 'open', o), (gen_random_uuid(), c, 'msgt-' || tag || '-i2', lower(job), job, 'test', r, 'open', o);
  insert into pb_prod.site_log (user_id, company_id, client_item_id, kind, job_number, job_key, data) values
    (f1, c, 'msgt-' || tag || '-1', 'delay', job, lower(job), '{}'), (r, c, 'msgt-' || tag || '-2', 'delay', job, lower(job), '{}'), (p2, c, 'msgt-' || tag || '-3', 'delay', job, lower(job), '{}'),
    (wk, c, 'msgt-' || tag || '-4', 'delay', job, lower(job), '{}'), (wk, c, 'msgt-' || tag || '-5', 'delay', jobb, lower(jobb), '{}');
  insert into pb_prod.crew_links (company_id, foreman_id, pipelayer_id) values (c, f1, p1);
  insert into pb_pm.settings (company_id, tz) values (c, 'America/Chicago') on conflict (company_id) do update set tz = 'America/Chicago';

  -- ---- privileges (static): what the API can reach ----
  select count(*) into n from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
   where ns.nspname = 'public' and p.proname like 'pb\_msg\_%' and p.proname not like 'pb\_msg\_svc\_%' and not has_function_privilege('authenticated', p.oid, 'execute');
  insert into t_chk (name, ok, got) values ('1a every public pb_msg_* app function is executable by authenticated', n = 0, n::text);
  select count(*) into n from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
   where ((ns.nspname = 'public' and p.proname like 'pb\_msg\_%') or ns.nspname = 'pb_msg') and has_function_privilege('anon', p.oid, 'execute');
  insert into t_chk (name, ok, got) values ('1b anon can execute none of them', n = 0, n::text);
  select count(*) into n from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
   where (ns.nspname = 'pb_msg' or (ns.nspname = 'public' and p.proname like 'pb\_msg\_svc\_%')) and has_function_privilege('authenticated', p.oid, 'execute');
  insert into t_chk (name, ok, got) values ('1c authenticated can execute no private pb_msg.* and no service function', n = 0, n::text);
  select count(*) into n from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
   where ((ns.nspname = 'public' and p.proname like 'pb\_msg\_%') or ns.nspname = 'pb_msg') and not p.prosecdef and has_function_privilege('authenticated', p.oid, 'execute');
  insert into t_chk (name, ok, got) values ('1d no caller-rights (SECURITY INVOKER) function of ours is callable by authenticated', n = 0, n::text);
  insert into t_chk (name, ok, got) values ('1e the pb_msg schema and tables are closed to the API',
    not has_schema_privilege('authenticated', 'pb_msg', 'usage') and not has_schema_privilege('anon', 'pb_msg', 'usage')
    and not has_table_privilege('authenticated', 'pb_msg.messages', 'select'), '');
  select count(*) into n from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
   where ((ns.nspname = 'public' and p.proname like 'pb\_msg\_%') or ns.nspname = 'pb_msg') and p.prosecdef
     and not exists (select 1 from unnest(p.proconfig) cfg where cfg like 'search_path=%');
  insert into t_chk (name, ok, got) values ('1f every definer function pins search_path', n = 0, n::text);

  -- ---- job chat: who is in ----
  j := pg_temp.q(f2, format('select public.pb_msg_open_job(%L, %L)', job, f2));
  insert into t_chk (name, ok, got) values ('1g a foreman NOT assigned to the job cannot start its chat', j->>'err' = 'pb:not_in_chat', j::text);
  j := pg_temp.q(f1, format('select public.pb_msg_open_job(%L, %L)', job, f1));
  ch := (j->'chat'->>'id')::uuid;
  insert into t_chk (name, ok, got) values ('1h a foreman assigned to the job starts it (title Job <n>, pipelayers off)', ch is not null and j->'chat'->>'title' = 'Job ' || job and (j->'chat'->>'include_pipelayers')::boolean = false, j::text);
  j := pg_temp.q(o, format('select public.pb_msg_send(%L, %L, %L, %L, null, %L)', ch, 'cli-' || tag || '-001', 'Pipe truck at 7. Need two guys on the loader please, bring the slings', '[]', o));
  m1 := (j->'message'->>'id')::uuid;
  insert into t_chk (name, ok, got) values ('1i the company account posts (seq 1)', m1 is not null and (j->'message'->>'seq')::int = 1, j::text);
  s := pg_temp.e(pg_temp.q(pm, format('select public.pb_msg_fetch(%L, null, null, 50, %L)', ch, pm))) || '/' || pg_temp.e(pg_temp.q(f1, format('select public.pb_msg_fetch(%L, null, null, 50, %L)', ch, f1)))
    || '/' || pg_temp.e(pg_temp.q(r, format('select public.pb_msg_fetch(%L, null, null, 50, %L)', ch, r)));
  insert into t_chk (name, ok, got) values ('1j the assigned PM and the two assigned foremen read it', s = 'ok/ok/ok', s);
  s := pg_temp.e(pg_temp.q(mgr, format('select public.pb_msg_fetch(%L, null, null, 50, %L)', ch, mgr))) || '/' || pg_temp.e(pg_temp.q(pm2, format('select public.pb_msg_fetch(%L, null, null, 50, %L)', ch, pm2)))
    || '/' || pg_temp.e(pg_temp.q(wk, format('select public.pb_msg_fetch(%L, null, null, 50, %L)', ch, wk)));
  insert into t_chk (name, ok, got) values ('1j2 the manager reads; a PM not assigned to this job does not; a foreman who only worked it (others are assigned) does not', s = 'ok/pb:not_in_chat/pb:not_in_chat', s);
  j := pg_temp.q(wk, format('select public.pb_msg_open_job(%L, %L)', jobb, wk)); chb := (j->'chat'->>'id')::uuid;
  s := pg_temp.e(j) || '/' || pg_temp.e(pg_temp.q(pm2, format('select public.pb_msg_fetch(%L, null, null, 50, %L)', chb, pm2))) || '/' || pg_temp.e(pg_temp.q(f1, format('select public.pb_msg_fetch(%L, null, null, 50, %L)', chb, f1)));
  j := pg_temp.q(o, format('select public.pb_msg_info(%L, %L)', chb, o));
  insert into t_chk (name, ok, got) values ('1j3 a job nobody is assigned to: the foreman who worked it starts the chat, every PM is in, other foremen are not; Chat info says it is the fallback',
    s = 'ok/ok/pb:not_in_chat' and j->'rule'->>'pms' = 'all' and j->'rule'->>'foremen' = 'worked', s || ' ' || coalesce((j->'rule')::text, ''));
  j := pg_temp.q(pm, format('select public.pb_msg_info(%L, %L)', ch, pm));
  insert into t_chk (name, ok, got) values ('1j4 the assigned job''s Chat info says assigned', j->'rule'->>'pms' = 'assigned' and j->'rule'->>'foremen' = 'assigned', coalesce((j->'rule')::text, ''));
  s := pg_temp.e(pg_temp.q(f2, format('select public.pb_msg_fetch(%L, null, null, 50, %L)', ch, f2))) || '/' || pg_temp.e(pg_temp.q(p1, format('select public.pb_msg_fetch(%L, null, null, 50, %L)', ch, p1)))
    || '/' || pg_temp.e(pg_temp.q(p2, format('select public.pb_msg_fetch(%L, null, null, 50, %L)', ch, p2)));
  insert into t_chk (name, ok, got) values ('1k a foreman not assigned, and pipelayers (switch off) cannot read', s = 'pb:not_in_chat/pb:not_in_chat/pb:not_in_chat', s);
  j := pg_temp.q(p1, format('select public.pb_msg_list(%L)', p1));
  insert into t_chk (name, ok, got) values ('1l the job chat is not in a pipelayer''s list while pipelayers are off', jsonb_array_length(j->'chats') = 0 and (j->>'member')::boolean, j::text);
  s := pg_temp.e(pg_temp.q(x, format('select public.pb_msg_fetch(%L, null, null, 50, %L)', ch, x))) || '/' || pg_temp.e(pg_temp.q(x, format('select public.pb_msg_open_dm(%L, %L)', o, x)))
    || '/' || pg_temp.e(pg_temp.q(x, format('select public.pb_msg_send(%L, %L, %L, %L, null, %L)', ch, 'cli-' || tag || '-x01', 'hi', '[]', x)))
    || '/' || (pg_temp.q(x, format('select public.pb_msg_list(%L)', x))->'chats')::text;
  insert into t_chk (name, ok, got) values ('1m someone from ANOTHER company: no read, no DM to us, no post, nothing listed', s = 'pb:not_in_chat/pb:not_in_chat/pb:not_in_chat/[]', s);
